add("train val loop", "num_epochs = ${1:10}\nbest_val_acc = 0.0\n\nfor epoch in range(num_epochs):\n    print(f'Epoch {epoch+1}/{num_epochs}')\n    print('-' * 10)\n    \n    # Training phase\n    model.train()\n    running_loss = 0.0\n    correct = 0\n    total = 0\n    \n    for inputs, labels in ${2:train_loader}:\n        inputs, labels = inputs.to(device), labels.to(device)\n        \n        optimizer.zero_grad()\n        outputs = model(inputs)\n        loss = criterion(outputs, labels)\n        loss.backward()\n        optimizer.step()\n        \n        running_loss += loss.item() * inputs.size(0)\n        _, predicted = torch.max(outputs.data, 1)\n        total += labels.size(0)\n        correct += (predicted == labels).sum().item()\n    \n    epoch_loss = running_loss / len(${2:train_loader}.dataset)\n    epoch_acc = correct / total\n    print(f'Train Loss: {epoch_loss:.4f} Acc: {epoch_acc:.4f}')\n    \n    # Validation phase\n    model.eval()\n    running_loss = 0.0\n    correct = 0\n    total = 0\n    \n    with torch.no_grad():\n        for inputs, labels in ${3:val_loader}:\n            inputs, labels = inputs.to(device), labels.to(device)\n            outputs = model(inputs)\n            loss = criterion(outputs, labels)\n            \n            running_loss += loss.item() * inputs.size(0)\n            _, predicted = torch.max(outputs.data, 1)\n            total += labels.size(0)\n            correct += (predicted == labels).sum().item()\n    \n    epoch_loss = running_loss / len(${3:val_loader}.dataset)\n    epoch_acc = correct / total\n    print(f'Val Loss: {epoch_loss:.4f} Acc: {epoch_acc:.4f}')\n    \n    # Save best model\n    if epoch_acc > best_val_acc:\n        best_val_acc = epoch_acc\n        torch.save(model.state_dict(), 'best_model.pth')\n        print('Best model saved!')\n    \n    print()\n\nprint(f'Best Val Acc: {best_val_acc:.4f}')\n$0", "Training loop with validation")
